CREATE TABLE IF NOT EXISTS devices (id uuid PRIMARY KEY, name text NOT NULL, public_key jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY, name text NOT NULL, owner_identity_id uuid NOT NULL, recovery_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS identities (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name text NOT NULL);
CREATE TABLE IF NOT EXISTS memberships (workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices(id), identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE, revoked_at timestamptz, PRIMARY KEY(workspace_id,device_id));
CREATE TABLE IF NOT EXISTS pages (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, parent_id uuid REFERENCES pages(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('document','database')), title text NOT NULL, revision integer NOT NULL DEFAULT 0, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), is_inbox boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS challenges (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, nonce text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS grants (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE, identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('editor','commenter','viewer')), include_descendants boolean NOT NULL DEFAULT false, revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS invites (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE, role text NOT NULL, include_descendants boolean NOT NULL, secret_hash text NOT NULL, expires_at timestamptz NOT NULL, redeemed_identity_id uuid REFERENCES identities(id) ON DELETE CASCADE, revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS document_updates (id bigserial PRIMARY KEY, page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE, operation_id uuid NOT NULL UNIQUE, data bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_checkpoints (page_id uuid PRIMARY KEY REFERENCES pages(id) ON DELETE CASCADE, data bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS metadata_operations (operation_id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices(id) ON DELETE CASCADE, result jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY, page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE, identity_id uuid NOT NULL REFERENCES identities(id) ON DELETE CASCADE, parent_id uuid REFERENCES comments(id) ON DELETE CASCADE, body text NOT NULL, resolved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE comments DROP CONSTRAINT IF EXISTS comments_identity_id_fkey;
ALTER TABLE comments ADD CONSTRAINT comments_identity_id_fkey FOREIGN KEY(identity_id) REFERENCES identities(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS pages_workspace ON pages(workspace_id);
CREATE INDEX IF NOT EXISTS updates_page ON document_updates(page_id,id);
CREATE INDEX IF NOT EXISTS grants_identity ON grants(identity_id,page_id);
CREATE INDEX IF NOT EXISTS comments_page ON comments(page_id,created_at);
